<section class="panel"><h2 class="h5">Change my password</h2><form method="post" action="/account/password">@csrf<div class="row g-3"><label class="col-md-4">Current password<input class="form-control" type="password" name="current_password" autocomplete="current-password" required></label><label class="col-md-4">New password<input class="form-control" type="password" name="password" minlength="12" autocomplete="new-password" required></label><label class="col-md-4">Confirm new password<input class="form-control" type="password" name="password_confirmation" minlength="12" autocomplete="new-password" required></label></div><button class="btn btn-primary mt-3">Update password</button></form></section>